import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { HERO, TOKENS } from './data';
import { delayOf, Headline, LANDING } from './headline';

/** The display rule of the home page: tight tracking on the display title and on nothing else. */
const DISPLAY =
  'text-[2.75rem] leading-[1.04] font-semibold tracking-[-0.03em] text-balance @2xl:text-7xl @5xl:text-8xl @5xl:leading-[1.02]';

export default function Heroes11() {
  const lastIndex = TOKENS.length;
  const leadIndex = lastIndex + 1;
  const actionsIndex = lastIndex + 2;

  return (
    <section className='@container'>
      <div className='relative isolate'>
        <Wash className='h-[30rem]' />
        <div className='mx-auto flex max-w-6xl flex-col items-center gap-8 px-4 py-16 text-center @2xl:gap-10 @2xl:px-6 @2xl:py-28'>
          <h1 className={cn(DISPLAY, 'max-w-5xl')}>
            <Headline />
          </h1>
          <p
            style={delayOf(leadIndex)}
            className={cn(
              'text-muted-foreground max-w-xl text-base text-pretty @2xl:text-lg',
              LANDING
            )}
          >
            {HERO.description}
          </p>
          <div
            style={delayOf(actionsIndex)}
            className={cn('flex flex-wrap justify-center gap-2', LANDING)}
          >
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {HERO.primaryAction}
              <ArrowRightIcon />
            </Button>
            <Button
              size='lg'
              variant='outline'
              nativeButton={false}
              render={<a href='#' />}
            >
              {HERO.secondaryAction}
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
}

import { Fragment } from 'react';

import {
  BotIcon,
  type Icon,
  RouteIcon,
  ShieldCheckIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';

import { type MarkId, TOKENS } from './data';

const STAGGER_MS = 70;

/**
 * What each part does once on load: it sharpens and rises 12px. The starting values come from the
 * browser's first style, so nothing runs in script, and reduced motion keeps only the fade.
 */
export const LANDING =
  'transition-[opacity,translate,filter] duration-700 ease-(--ease-out-strong) starting:opacity-0 motion-safe:starting:translate-y-3 motion-safe:starting:blur-sm';

export function delayOf(index: number) {
  return { transitionDelay: `${index * STAGGER_MS}ms` };
}

const MARK_ICONS: Record<MarkId, Icon> = {
  plan: RouteIcon,
  agent: BotIcon,
  review: ShieldCheckIcon,
};

function MarkTile({ mark, index }: { mark: MarkId; index: number }) {
  const Glyph = MARK_ICONS[mark];

  return (
    <>
      <span className='sr-only'>, </span>
      <span
        aria-hidden='true'
        style={delayOf(index)}
        className={cn(
          'keycap-3d relative -top-[0.04em] inline-flex size-[0.72em] items-center justify-center rounded-[0.22em] align-middle',
          LANDING
        )}
      >
        <Glyph className='text-foreground/80 size-[0.42em]' />
      </span>
    </>
  );
}

export function Headline() {
  return (
    <>
      {TOKENS.map((token, index) => (
        <Fragment key={token.id}>
          {index > 0 && ' '}
          {token.kind === 'mark' && (
            <MarkTile mark={token.mark} index={index} />
          )}
          {token.kind === 'word' && (
            <span
              style={delayOf(index)}
              className={cn('inline-block', LANDING)}
            >
              {token.text}
            </span>
          )}
        </Fragment>
      ))}
    </>
  );
}

export type MarkId = 'plan' | 'agent' | 'review';

export type Token =
  | { id: string; kind: 'word'; text: string }
  | { id: string; kind: 'mark'; mark: MarkId };

export const HERO = {
  description:
    'Describe the outcome you want. Agents break it into steps, do the work in the open, and stop for your approval before anything leaves your workspace.',
  primaryAction: 'Start a project',
  secondaryAction: 'Watch a run',
};

export const TOKENS: Token[] = [
  { id: 'plan', kind: 'word', text: 'Plan' },
  { id: 'the', kind: 'word', text: 'the' },
  { id: 'work', kind: 'word', text: 'work' },
  { id: 'plan-mark', kind: 'mark', mark: 'plan' },
  { id: 'hand', kind: 'word', text: 'hand' },
  { id: 'it', kind: 'word', text: 'it' },
  { id: 'to', kind: 'word', text: 'to' },
  { id: 'an', kind: 'word', text: 'an' },
  { id: 'agent', kind: 'word', text: 'agent' },
  { id: 'agent-mark', kind: 'mark', mark: 'agent' },
  { id: 'review', kind: 'word', text: 'review' },
  { id: 'what', kind: 'word', text: 'what' },
  { id: 'ships', kind: 'word', text: 'ships' },
];
